mapper.select:
SELECT session_id, tenant_id, principal_id, principal_type, display_name,
       created_at, last_activity_at, revision
FROM sdk_conversation WHERE session_id = #{sessionId}

SELECT session_id, tenant_id, principal_id, principal_type, display_name,
       created_at, last_activity_at, revision
FROM sdk_conversation
WHERE tenant_id = #{tenantId}
  AND principal_id = #{principalId}
  AND principal_type = #{principalType}

  AND lower(display_name) LIKE '%' || lower(#{text}) || '%' ESCAPE '\'


  AND (last_activity_at < #{afterAt}
       OR (last_activity_at = #{afterAt} AND session_id < #{afterSessionId}))

ORDER BY last_activity_at DESC, session_id DESC
LIMIT #{limit}

mapper.update:
